lid #b86529;outline-offset:3px}.full{width:100%;margin-top:24px}.badge{display:inline-block;font-size:11px;padding:5px 10px;border-radius:20px;background:#edf1e7;color:#43674e;margin:5px 0 12px}.result{background:#173f34;color:white;position:sticky;top:20px}.result .muted,.result small{color:#c3d2c5}.result .badge{background:#2e5846;color:#d5e7c4}.amount{font-size:clamp(40px,5vw,65px);letter-spacing:-3px;line-height:1.2;font-weight:650}.amount em{font-size:20px;letter-spacing:0}.annual{margin:10px 0 22px;color:#cfe0cf}.line{display:flex;justify-content:space-between;gap:15px;padding:9px 0;border-bottom:1px solid #ffffff24;font-size:14px}.line.total{font-weight:750;border:0}.control{padding:18px 0;border-bottom:1px solid #e7ebe5}.control label{display:flex;justify-content:space-between;align-items:center;gap:16px}.control input[type=number]{width:100px;margin:0}.control input[type=range]{width:100%;accent-color:#396547;margin:14px 0 0}.actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:20px}.note{background:#fbefe3;color:#6f4d32;border-radius:16px;padding:15px;font-size:13px;margin-top:20px}details{margin-top:18px}summary{cursor:pointer;font-weight:650}.comparison{margin-top:18px;padding:16px;background:#ffffff12;border-radius:16px}.bar{height:8px;display:flex;border-radius:20px;overflow:hidden;margin:20px 0}.bar span:first-child{background:#c9df9d}.bar span:last-child{background:#eaa171}.empty{padding:30px 0;color:#c8d8ca}footer{padding:25px 0 45px;font-size:12px;color:#6c7d72}[hidden]{display:none!important}.fade{animation:in .4s ease-out}@keyframes in{from{opacity:.4;transform:translateY(8px)}to{opacity:1;transform:none}}@media(max-width:760px){.grid{grid-template-columns:1fr}.wrap{padding:0 16px}header{padding:30px;min-height:340px}header img{width:100%;opacity:.23}h1{letter-spacing:-2px}.card{padding:23px}.result{position:static}.fields{gap:12px}}@media(prefers-reduced-motion:reduce){*{animation:none!important;scroll-behavior:auto!important}}@media print{nav,header,.editor,.actions,footer{display:none}.grid{display:block}.result{position:static;background:white;color:#163d32}.result small,.result .muted{color:#52675a}}

