calc.script:
const portfolio={"bratislava|1": {"count": 66, "adr": 68.57}, "kosice|1": {"count": 15, "adr": 45.71}, "bratislava|3": {"count": 4, "adr": 153.65}, "bratislava|2": {"count": 28, "adr": 101.43}, "kosice|2": {"count": 5, "adr": 83.5}};
const stayStats={"bratislava|1": {"guests": 1.73, "stay": 3.77, "n": 1126, "listings": 66}, "kosice|1": {"guests": 1.43, "stay": 4.46, "n": 235, "listings": 15}, "bratislava|3": {"guests": 5.03, "stay": 2.91, "n": 79, "listings": 4}, "bratislava|2": {"guests": 3.3, "stay": 3.64, "n": 472, "listings": 28}, "kosice|2": {"guests": 3.08, "stay": 4.56, "n": 62, "listings": 5}};
const defs=[['adr',"Price per occupied night",'€',0,500,.01,100,"Initially based on the portfolio; once edited, it becomes your own assumption."],['occupancy',"Occupancy of available nights",'%',0,100,1,65,"The initial 65% is an illustrative assumption, not a measured occupancy."],['own',"Nights for you / blocked nights","nights",0,30,1,0,"They reduce the number of nights offered for rent."]];
const costs=[['portal',"Platform fees",'%',0,30,.5,0,"So far 0%: not entered. Only set fees that have not yet been deducted."],['clean',"Cost per cleaning",'€',0,150,.5,32.5,"Smaller apartment: €30–35, larger: €40–50. A LIVE-IN assumption, not an average from invoices."],['cleanPaid',"Guest cleaning payment per stay",'€',0,150,.5,0,"Default €0. Enter the net payment only if it is not already included in the night's income; otherwise it would be counted twice."],['avgGuests',"Average number of guests per reservation","guests",1,30,.01,2,"Average from bookings of comparable apartments, capped at your apartment’s capacity. You can adjust it. It does not affect the nightly rate or cleaning cost."],['stay',"Average length of stay","nights",1,365,.01,3,"Average from historical bookings; one cleaning after each stay. You can adjust it."],['fixed',"Energy and other monthly costs",'€',0,2000,10,0,"Not entered yet. Include internet, insurance and a reserve for repairs."]];
let initial=null,snapshot=null,initialSize="small";
const el=id=>document.getElementById(id),fmt=v=>new Intl.NumberFormat("en-GB",{style:'currency',currency:'EUR',maximumFractionDigits:0}).format(v),cent=v=>Math.round((v+Number.EPSILON)*100)/100;
function renderControls(list,target){el(target).innerHTML=list.map(([id,label,unit,min,max,step,val,hint])=>`<div class="control"><label for="${id}">${label} (${unit})<input id="${id}" type="number" min="${min}" max="${max}" step="${step}" value="${val}" required></label><input id="${id}Range" type="range" aria-label="${label}" min="${min}" max="${max}" step="${step}" value="${val}"><small>${hint}</small></div>`).join('');}
renderControls(defs,'controls');renderControls(costs,'costControls');
function values(){return Object.fromEntries([...defs,...costs].map(d=>[d[0],Number(el(d[0]).value)]));}
function calculate(v){const nights=(30-v.own)*v.occupancy/100,gross=cent(nights*v.adr),portal=cent(gross*v.portal/100),income=cent(gross-portal),management=Math.round(Math.round(income*100)*17/100)/100,vat=Math.round(Math.round(income*100)*5/100)/100,bookings=nights/v.stay,guestVisits=bookings*v.avgGuests,cleanGross=cent(bookings*v.clean),cleanRecovery=cent(bookings*v.cleanPaid),clean=cent(cleanGross-cleanRecovery),net=cent(income-management-vat-clean-50-v.fixed);return{nights,bookings,guestVisits,cleanGross,cleanRecovery,gross,portal,income,management,vat,clean,net};}
function update(){if(!initial)return;for(const d of [...defs,...costs]){const field=el(d[0]);if(field.value===''||!Number.isFinite(+field.value)||+field.value<d[3]||+field.value>Number(field.max)){el('print').disabled=true;el('netBar').style.width='0%';el('costBar').style.width='0%';el('net').textContent="Enter a valid value";el('annual').textContent='';el('ledger').textContent="The result will update once the input is corrected.";el('comparison').hidden=true;return;}}
el('print').disabled=false;const v=values(),r=calculate(v);el('net').textContent=fmt(r.net);el('annual').textContent="30-day scenario · including cleaning estimate";el('ledger').innerHTML=[["Occupied nights",r.nights.toLocaleString("en-GB",{maximumFractionDigits:1})+' / '+(30-v.own)],["Estimated revenue",fmt(r.gross)],["Platform fees",'− '+fmt(r.portal)],["Estimated Rental Income",fmt(r.income)],["Management fee · 17%",'− '+fmt(r.management)],["VAT · 5% as specified",'− '+fmt(r.vat)],["Estimated bookings / cleanings",r.bookings.toLocaleString("en-GB",{maximumFractionDigits:1})],["Guests per booking",v.avgGuests.toLocaleString("en-GB",{maximumFractionDigits:2})],["Estimated guest arrivals per month",r.guestVisits.toLocaleString("en-GB",{maximumFractionDigits:1})],["Total cleaning cost",'− '+fmt(r.cleanGross)],["Cleaning payments from guests",'+ '+fmt(r.cleanRecovery)],["Guesty / month",'− 50 €'],["Additional costs entered",'− '+fmt(v.fixed)]].map(x=>`<div class="line"><span>${x[0]}</span><b>${x[1]}</b></div>`).join('');const share=r.gross?Math.min(100,Math.max(0,r.net/r.gross*100)):0;el('netBar').style.width=share+'%';el('costBar').style.width=(100-share)+'%';if(snapshot){el('comparison').hidden=false;el('comparison').textContent="Compared with the saved scenario: "+(r.net-snapshot.net>=0?'+':'')+fmt(r.net-snapshot.net)+' / month (previously '+fmt(snapshot.net)+').';}}
for(const d of [...defs,...costs])for(const suffix of ['', 'Range'])el(d[0]+suffix).addEventListener('input',()=>{el(d[0]+(suffix?'':'Range')).value=el(d[0]+suffix).value;update();});
el('profile').addEventListener('submit',e=>{e.preventDefault();if(!el('profile').reportValidity())return;const segment=portfolio[el('city').value+'|'+el('bedrooms').value];if(!segment){el('profileError').textContent="We do not yet have at least 3 comparable apartments for this apartment type. An individual assessment is required, so we do not provide an automatic rate.";el('adjust').hidden=true;el('numbers').hidden=true;el('empty').hidden=false;initial=null;return;}el('profileError').textContent='';snapshot=null;el('comparison').hidden=true;for(const d of [...defs,...costs]){el(d[0]).value=d[0]==='adr'?segment.adr:d[6];el(d[0]+'Range').value=el(d[0]).value;}const historical=stayStats[el('city').value+'|'+el('bedrooms').value];el('cleanSize').value=(+el('bedrooms').value>=2||+el('area').value>=70)?'large':'small';for(const [id,value] of Object.entries({clean:el('cleanSize').value==='large'?45:32.5,stay:historical?historical.stay:3,avgGuests:Math.min(+el('guests').value,historical?historical.guests:2)})){el(id).value=value;el(id+'Range').value=value;}el('avgGuests').max=el('guests').value;el('avgGuestsRange').max=el('guests').value;initialSize=el('cleanSize').value;initial=values();el('evidence').textContent=`${segment.count} comparable listings by city and bedroom count. Historical rate: ${fmt(segment.adr)}/night. Profile: ${el('area').value} m², ${el('guests').value} guests, ${el('location').selectedOptions[0].textContent.toLowerCase()}, ${el('standard').selectedOptions[0].textContent.toLowerCase()} standard.`;el('evidence').textContent+=historical?` Number of guests and length of stay: ${historical.n} uncancelled reservations in ${historical.listings} listings, with check-out dates from July to September 2026. Average guests ${historical.guests}, stay ${historical.stay} nights. These booking figures come from the snapshot dated 12 October 2026; completed stays have not been verified against accounting records. The average guest count is capped at the apartment’s capacity.`:" We use illustrative assumptions for guests and length of stay.";el('adjust').hidden=false;el('numbers').hidden=false;el('empty').hidden=true;el('numbers').classList.add('fade');update();if(matchMedia('(max-width: 800px)').matches){el('result').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});el('result').focus({preventScroll:true});}});
el('cleanSize').addEventListener('change',()=>{el('clean').value=el('cleanSize').value==='large'?45:32.5;el('cleanRange').value=el('clean').value;update();});
el('reset').addEventListener('click',()=>{if(!initial)return;el('cleanSize').value=initialSize;for(const [id,v]of Object.entries(initial)){el(id).value=v;el(id+'Range').value=v;}update();});el('save').addEventListener('click',()=>{if([...defs,...costs].some(d=>!el(d[0]).checkValidity()))return;snapshot=calculate(values());update();});
for(const id of ['city','bedrooms','location','standard','area','guests'])el(id).addEventListener('input',()=>{if(initial){el('profileError').textContent="The profile has changed. Click “View my scenario” to update the comparable apartments and settings.";el('adjust').hidden=true;el('numbers').hidden=true;el('empty').hidden=false;initial=null;}});
